type lane=Mechanical|Ownership|Metadata
type package=Destination|Descriptor_graph|Scope_graph|Capture_lifecycle|Type_metadata
type item={id:string;lane:lane;package:package;operation:string;tests:string list}
let mechanical_ids=["method:-[MTLCaptureDescriptor destination]";"property:MTLCaptureDescriptor:destination"]
let callable_ids=["method:-[MTLCaptureDescriptor captureObject]";"method:-[MTLCaptureDescriptor destination]";"method:-[MTLCaptureDescriptor outputURL]";"method:-[MTLCaptureDescriptor setCaptureObject:]";"method:-[MTLCaptureDescriptor setOutputURL:]";"method:-[MTLCaptureManager defaultCaptureScope]";"method:-[MTLCaptureManager newCaptureScopeWithCommandQueue:]";"method:-[MTLCaptureManager newCaptureScopeWithDevice:]";"method:-[MTLCaptureManager newCaptureScopeWithMTL4CommandQueue:]";"method:-[MTLCaptureManager setDefaultCaptureScope:]";"method:-[MTLCaptureManager startCaptureWithCommandQueue:]";"method:-[MTLCaptureManager startCaptureWithDescriptor:error:]";"method:-[MTLCaptureManager startCaptureWithDevice:]";"method:-[MTLCaptureManager startCaptureWithScope:]";"method:-[MTLCaptureManager stopCapture]";"property:MTLCaptureDescriptor:captureObject";"property:MTLCaptureDescriptor:destination";"property:MTLCaptureDescriptor:outputURL";"property:MTLCaptureManager:defaultCaptureScope"]
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify~kind id=let lane=if List.mem id mechanical_ids then Mechanical else if kind="method"||kind="property"then Ownership else Metadata in let package,operation,tests=if lane=Metadata then Type_metadata,"Metal.Capture opaque descriptor/manager types",["public type provenance"]else if lane=Mechanical then Destination,"Metal.Capture_descriptor.destination",["typed enum round trip";"availability"]else if contains id "MTLCaptureDescriptor"then Descriptor_graph,"Metal.Capture_descriptor",["capture-object exact kind";"URL/destination compatibility";"mutation ownership"]else if contains id "startCapture"||contains id "stopCapture"then Capture_lifecycle,"Metal.Capture_manager start/stop",["single active capture state";"error rollback";"destroyed-source rejection"]else Scope_graph,"Metal.Capture_manager scope",["device/queue identity";"default-scope retention";"MTL4 availability"]in{id;lane;package;operation;tests}
let validate items=let count f=List.length(List.filter f items)in if List.length items<>21||count(fun x->x.lane=Mechanical)<>2||count(fun x->x.lane=Ownership)<>17||count(fun x->x.lane=Metadata)<>2||List.map(fun p->count(fun x->x.package=p))[Destination;Descriptor_graph;Scope_graph;Capture_lifecycle;Type_metadata]<>[2;6;6;5;2]then failwith"CaptureManager21 tail drift"
